import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`backlink-gap`,heroTitle:`Find your backlink gaps in minutes`,heroSubtitle:`Perplexity Computer crawls backlink profiles, identifies high-authority sites linking to competitors but not you, and delivers a prioritized outreach spreadsheet — automatically.`,inputUrlCta:`Find my backlink gaps`,inputUrlPlaceholder:`www.yoursite.com`,inputUrlPrefill:`Go to {url} and identify the domain. Then find 3-5 top competitors in the same space. For each competitor: 1) Crawl their backlink profile and identify all referring domains with Domain Authority 40+. 2) Compare against the backlink profile of {url} to find domains linking to competitors but not to this site. 3) Categorize gap opportunities by type — guest post, resource page, directory, editorial mention, broken link. 4) Score each opportunity by domain authority, relevance, and estimated outreach difficulty. 5) Generate a personalized outreach email template for each opportunity type. 6) Deliver a prioritized outreach spreadsheet with: domain, DA, link type, competitor URL being linked, suggested pitch angle, and draft email.`,heroOverlaySteps:[`Crawling your backlink profile and identifying top competitors`,`Comparing referring domains to find sites linking to competitors but not you`,`Scoring gap opportunities by authority, relevance, and outreach difficulty`,`Prioritized outreach list with draft emails — ready to send`],generatingSteps:[`Visiting {url} to analyze your current backlink profile and domain authority`,`Designing an agent to crawl competitor backlink profiles and compare referring domains`,`Configuring gap analysis with scoring by authority, relevance, and difficulty`,`Setting up outreach spreadsheet generation with personalized email templates`],featureSectionTitle:`From audit to outreach`,featureCardTitles:[`Connects to your SEO stack`,`Outreach ready to send`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Ahrefs, Google Search Console, Google Sheets, Gmail, Notion — Computer plugs into your tools so gap analysis and outreach happen in one workflow.`,`Gap analysis reports. Domain-scored opportunity lists. Personalized pitch emails. Computer delivers a complete outreach package ready for your link building campaign.`],capabilitySectionTitle:`Your link building team, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a prioritized backlink outreach plan.`,capabilityCards:[{title:`Backlink Crawling`,description:`Computer can crawl backlink profiles across your site and competitors — extracting referring domains, anchor text, and domain authority scores.`},{title:`Gap Analysis`,description:`Computer can compare backlink profiles side by side and surface high-authority domains linking to competitors but not to you — ranked by opportunity value.`},{title:`Outreach Drafting`,description:`Computer can generate personalized outreach emails for each link opportunity — tailored by link type, pitch angle, and the specific page being referenced.`},{title:`Connect Your Tools`,description:`Computer can read and write to Ahrefs, Google Sheets, Gmail, Notion, and more — build workflows across your entire SEO and outreach stack.`},{title:`Remember & Learn`,description:`Computer can remember your domain, competitors, and past outreach results across sessions — so every new gap analysis builds on what worked before.`},{title:`Monitor & Alert`,description:`Computer can track new backlinks your competitors acquire and alert you when fresh gap opportunities appear — keeping your outreach pipeline full.`}]});export{t as default};
